isHomePage() {
  // Home now lives at "/:projectName" (name 'home'); "/" is the unscoped
  // bootstrap route (name 'root') used before a project is active.
  return this.$route.name === 'home'
    || this.$route.name === 'root'
    || this.$route.path === '/'
