      const socket = $storex.api.socket
      if (!socket) return

      socket.off('codx-junior-index-progress-started')
      socket.off('codx-junior-index-progress-document-processing')
      socket.off('codx-junior-index-progress-document-enriched')
      socket.off('codx-junior-index-progress-document-indexed')
      socket.off('codx-junior-index-progress-batch-complete')
      socket.off('codx-junior-index-progress-completed')
      socket.off('codx-junior-index-error')
    },

    /**
     * Keep the URL's project base path ("/:projectName/…") in sync with the
     * active project. The unscoped "root" route is promoted to the scoped
     * home once a project is active. No-op when the URL already matches.
     */
    syncRouteProjectPrefix(_, project) {
      const router = $storex.$router
      const current = router?.currentRoute?.value
      if (!router || !project?.project_name) return
      if (!current?.name || current.name === 'mobile') return

      const projectName = encodeURIComponent(project.project_name)
      const targetName = current.name === 'root' ? 'home' : current.name

      // Already scoped to the right project – nothing to do.
      if (current.name !== 'root' && current.params?.projectName === projectName) {
        return
      }

      router.replace({
        name: targetName,
        params: { ...(current.params || {}), projectName },
        query: current.query
      }).catch(() => {})
    },

    async saveLastActiveProject() {
      try {
        const projectId = $storex.projects?.activeProject?.project_id
        if (projectId) {
          localStorage.setItem('lastActiveProject', projectId)
        }
      } catch (error) {
        console.error('Failed to save last active project:', error)
      }
    },

    async initProjectState({ state }, project) {
      const targetProject = project || state.activeProject
      if (!targetProject) {
        throw new Error('No project provided or active project set')
      }

      // Ensure project is initialized
      if (!targetProject.$state) {
        targetProject.$state = createState()
        targetProject.$state.status = ENTITY_STATUS.UNINITIALIZED
      }

      // Initialize if not already done
      if (targetProject.$state.status === ENTITY_STATUS.UNINITIALIZED) {
        await initProject(targetProject)
      }

      return targetProject.$state
    },

    createSearchController() {
      return new MentionSearchController()
    }
  }
